func TestViewportFollowSelectionAndOffset(t *testing.T) {
	vp := newViewport(20, 5).FollowSelection(0, 0)
	if vp.offset != 0 {
		t.Fatalf("top offset = %d", vp.offset)
	}
	vp = newViewport(20, 5).FollowSelection(12, 12)
